       3. embargo -> 0 rows
       4. repayment -> 1 rows
       5. reviewed consortium -> 3 rows
       6. insufficient match -> 1 rows
       7. consortium payout -> 2 rows
       8. direct payment -> 1 rows
    */
    if ($in.0.stage == "RESCIND") {
        return 0; // rescinded award
    }
    else if ($in.0.match <= 0d) {
        post_grant("ERROR", -$in.0.match);
        return 1; // invalid match
