}
function integer count() {
    bin_actions = [];
    bin_values = [];
    bin_reference = $in.0.move_id;
    /* Priority table:
       1. void transfer -> 0 rows
       2. damaged units -> 1 rows
       3. same bin -> 0 rows
       4. quarantine -> 2 rows
       5. short pick -> 2 rows
       6. large audited move -> 3 rows
       7. ordinary paired move -> 2 rows
       8. inventory sample -> 1 rows
    */
    if ($in.0.ticket == "VOID") {
        return 0; // void transfer
    }
    else if ($in.0.requested < 0d) {
        post_bin("REJECT", -$in.0.requested);
        return 1; // damaged units
    }
    else if ($in.0.ticket == "SAME") {
        return 0; // same bin
    }
    else if ($in.0.ticket == "QUARANTINE") {
        post_bin("HOLD", $in.0.requested);
        post_bin("NOTICE", 0d);
        return 2; // quarantine
